import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { createCore, createG7221 } from '../js/index.mjs'
const wasm = readFileSync(new URL('../dist/yki-core.wasm', import.meta.url))
const reference = JSON.parse(readFileSync(new URL('./g7221/reference.json', import.meta.url)))
const sha = (b) => createHash('sha256').update(b).digest('hex')
test('MoonBit codec matches C reference bitstreams and PCM for 500 frames', async () => {
  // Captured from the old C implementation, not generated by MoonBit.
  // No C source, compiler, FFmpeg, or host callback is needed to run this test.
  const codec = await createG7221(wasm)
  let seed = reference.seed
  for (const vector of reference.vectors) {
    const pcm = Buffer.alloc(640 * reference.frames)
    for (let i = 0; i < pcm.length / 2; i++) {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0
      const value =
        vector.kind === 'sine'
          ? Math.round(Math.sin((i * 2 * Math.PI * 440) / 16000) * 15000)
          : vector.kind === 'noise'
            ? (seed >>> 16) - 32768
            : vector.kind === 'impulse'
              ? i % 320 === 0
                ? 32767
                : 0
              : vector.kind === 'clipping'
                ? i % 2
                  ? 32767
                  : -32768
                : 0
      pcm.writeInt16LE(value, i * 2)
    }
    const encoded = codec.encode(pcm)
    assert.equal(Buffer.from(encoded).toString('hex'), vector.encoded, vector.kind)
    assert.equal(
      sha(codec.decode(Buffer.from(vector.encoded, 'hex'))),
      vector.decodedSHA256,
      vector.kind,
    )
    assert.deepEqual(codec.encode(pcm), encoded, 'new calls reset frame history')
  }
})
test('host-free AU decoding, input bounds, malformed frames, and recovery', async () => {
  const core = await createCore(wasm, {
    host() {
      throw new Error('codec must not call host')
    },
  })
  for (const length of [0, 1, 639, 641])
    assert.throws(() => core.encodeG7221(new Uint8Array(length)), /complete/)
  for (const length of [0, 1, 39, 41])
    assert.throws(() => core.decodeG7221(new Uint8Array(length)), /complete/)
  let seed = 12345
  for (let attempt = 0; attempt < 100; attempt++) {
    const data = Uint8Array.from({ length: 40 * 3 }, () => {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0
      return seed >>> 24
    })
    assert.equal(core.decodeG7221(data).length, 640 * 3, 'malformed payload must not trap')
  }
  const payload = core.encodeG7221(new Uint8Array(640))
  const au = Buffer.alloc(72)
  au.write('AU')
  au.writeUInt32LE(1, 8)
  for (let i = 0; i < payload.length; i++) {
    let n = payload[i],
      reversed = 0
    for (let bit = 0; bit < 8; bit++) {
      reversed = (reversed << 1) | (n & 1)
      n >>= 1
    }
    au[32 + i] = reversed
  }
  assert.deepEqual(core.decode(au), core.decodeG7221(payload))
})
